public static int findNthLeapYear(int Y, int N) {
    if (Y < 1 || N < 1) {
        throw new IllegalArgumentException("Invalid input: Y and N must be positive integers.");
    }

    int leapYearCount = 0;
    for (int year = Y; year <= Y + N - 1; year++) {
        if (isLeapYear(year)) {
            leapYearCount++;
            if (leapYearCount == N) {
                return year;
            }
        }
    }

    throw new IllegalArgumentException("No leap year found after " + Y + " for position " + N);
}

private static boolean isLeapYear(int year) {
    return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
}

