        throw new IllegalArgumentException("N must be a positive integer");
    }

    int timeNeeded = 0;
    for (int i = 0; i < N; i++) {
        timeNeeded++;
        for (int j = 0; j < N - 1; j++) {
            if (j % 2 == 0) {
                if (i == j) {
