public int search(int[] nums, int target) {
    // Find the pivot index
    int pivot = findPivot(nums);

    // Search in the left and right subarrays
    int left = searchLeft(nums, 0, pivot - 1, target);
    int right = searchRight(nums, pivot, nums.length - 1, target);

    // Return the first match
    if (left != -1) {
        return left;
    } else if (right != -1) {
        return right;
    } else {
        return -1;
    }
}

private int findPivot(int[] nums) {
    // Find the pivot index
    int pivot = 0;
    for (int i = 1; i < nums.length; i++) {
        if (nums[i] < nums[pivot]) {
            pivot = i;
        }
    }
    return pivot;
}

private int searchLeft(int[] nums, int start, int end, int target) {
    // Search in the left subarray
    while (start <= end) {
        int mid = (start + end) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] < target) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }
    return -1;
}

private int searchRight(int[] nums, int start, int end, int target) {
    // Search in the right subarray
    while (start <= end) {
        int mid = (start + end) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] < target) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the smallest and largest 5%
    int numElementsToRemove = (int) (arr.length * 0.05);

    // Remove the smallest and largest 5% of elements
    int[] trimmedArr = Arrays.copyOfRange(arr, numElementsToRemove, arr.length - numElementsToRemove);

    // Calculate the mean of the remaining elements
    double mean = 0.0;
    for (int i = 0; i < trimmedArr.length; i++) {
        mean += trimmedArr[i];
    }
    mean /= trimmedArr.length;

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

