}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a set to store the visited nodes
    Set<Integer> visited = new HashSet<>();

    // Initialize a variable to store the minimum time
    int minTime = 0;

    // Start from node 0
    queue.offer(0);
    visited.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node
        int current = queue.poll();

        // If the current node has an apple, add the time to collect it
        if (hasApple[current]) {
            minTime++;
        }

        // Loop through the neighbors of the current node
        for (int neighbor : graph.getNeighbors(current)) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited.contains(neighbor)) {
                queue.offer(neighbor);
                visited.add(neighbor);
            }
        }
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();

    // Step 1: Pick the smallest character from s and append it to the result
    char smallest = s.charAt(0);
    result.append(smallest);

    // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c > smallest) {
            result.append(c);
            smallest = c;
        }
    }

    // Step 3: Repeat step 2 until you cannot pick more characters
    while (result.length() < s.length()) {
        smallest = Character.MAX_VALUE;

        // Step 4: Pick the largest character from s and append it to the result
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < smallest) {
                smallest = c;
            }
        }
        result.append(smallest);

        // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c > smallest && c < result.charAt(result.length() - 1)) {
                result.append(c);
            }
        }
    }

    return result.toString();
}

