public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence
    int[] fib = new int[] {1, 1};

    // Loop until the sum of the Fibonacci numbers is greater than or equal to k
    while (fib[fib.length - 1] + fib[fib.length - 2] < k) {
        // Add the next Fibonacci number to the sequence
        fib = Arrays.copyOf(fib, fib.length + 1);
        fib[fib.length - 1] = fib[fib.length - 2] + fib[fib.length - 3];
    }

    // Return the minimum number of Fibonacci numbers needed to sum up to k
    return fib.length;
}

