public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<int[]> permutations = new HashSet<>();

    // Loop through all possible permutations of the input array
    for (int[] permutation : permutations(A)) {
        // Check if the permutation is a square array
        if (isSquareArray(permutation)) {
            // If it is, add it to the set of unique permutations
            permutations.add(permutation);
        }
    }

    // Return the number of unique permutations
    return permutations.size();
}

private static boolean isSquareArray(int[] A) {
    // Loop through all adjacent pairs of elements in the array
    for (int i = 0; i < A.length - 1; i++) {
        // If the sum of the pair is not a perfect square, return false
        if (!isPerfectSquare(A[i] + A[i + 1])) {
            return false;
        }
    }

    // If all adjacent pairs are perfect squares, return true
    return true;
}

private static boolean isPerfectSquare(int x) {
    // Check if x is a perfect square by checking if its square root is an integer
    return Math.sqrt(x) % 1 == 0;
}

private static List<int[]> permutations(int[] A) {
    // If the input array has only one element, return a list with one element
    if (A.length == 1) {
        return Arrays.asList(A);
    }

    // Initialize an empty list to store the permutations
    List<int[]> permutations = new ArrayList<>();

    // Loop through all possible positions of the first element in the permutation
    for (int i = 0; i < A.length; i++) {
        // Recursively generate the permutations for the rest of the array
        List<int[]> subPermutations = permutations(Arrays.copyOfRange(A, i + 1, A.length));

        // Add the first element to each permutation of the rest of the array
        for (int[] subPermutation : subPermutations) {
            int[] permutation = new int[A.length];
            permutation[i] = A[i];
            System.arraycopy(subPermutation, 0, permutation, i + 1, subPermutation.length);
            permutations.add(permutation);
        }
    }

    // Return the list of permutations
    return permutations;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int height = heights[i];
        int width = 1;
        while (i + width < n && heights[i + width] >= height) {
            width++;
        }
        maxArea = Math.max(maxArea, height * width);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int[] result = new int[mat.length];
    int index = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (i == j) {
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Check if n is a valid input
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // Get the digits of n
    int[] digits = getDigits(n);

    // Sort the digits in descending order
    Arrays.sort(digits, Collections.reverseOrder());

    // Build the rearranged integer
    int rearrangedInteger = 0;
    for (int digit : digits) {
        rearrangedInteger = rearrangedInteger * 10 + digit;
    }

    // Check if the rearranged integer is greater than n
    if (rearrangedInteger > n) {
        return rearrangedInteger;
    } else {
        return -1;
    }
}

private static int[] getDigits(int n) {
    int[] digits = new int[Integer.toString(n).length()];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    return digits;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();

    for (int i = 0; i < n; i++) {
        String num = "";
        for (int j = 0; j < n; j++) {
            if (j == i) {
                num += "1";
            } else {
                num += "0";
            }
        }
        result.add(num);
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points are valid
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Calculate the slope of the three lines
    double slope1 = (double)(points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double slope2 = (double)(points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);
    double slope3 = (double)(points[0][1] - points[2][1]) / (points[0][0] - points[2][0]);

    // Check if the slopes are equal
    if (slope1 == slope2 && slope2 == slope3) {
        return true;
    }

    return false;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] factors = {2, 3, 5};
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        int minFactor = Integer.MAX_VALUE;
        for (int factor : factors) {
            if (uglyNumbers[i - 1] * factor < minFactor) {
                minFactor = uglyNumbers[i - 1] * factor;
            }
        }
        uglyNumbers[i] = minFactor;
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int maxEnergy = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            energy++;
        } else {
            maxEnergy = Math.max(energy, maxEnergy);
            energy = 1;
        }
    }
    return Math.max(energy, maxEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> a.compareTo(b));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    // Initialize a hash set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Iterate over the input array and add unique elements to the hash set
    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
        }
    }

    // Initialize the sum variable
    int sum = 0;

    // Iterate over the hash set and add elements to the sum
    for (int element : uniqueElements) {
        sum += element;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (Math.sqrt(i) % 1 == 0) {
            count++;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] chars = word.toCharArray();
        Arrays.reverse(chars);
        result.append(new String(chars));
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}
